node -e 'import("fs").then(fs => { const files = ["manifest.json", "versions.json", "package.json", "styles.css"]; const walk = d => fs.existsSync(d) && fs.readdirSync(d, { withFileTypes: true }).forEach(e => { const p = `${d}/${e.name}`; e.isDirectory() ? walk(p) : files.push(p); }); walk("src"); let out = "# Plugin Context
"; for (const f of files) { if (fs.existsSync(f)) { const ext = f.split(".").pop(); out += `
## ${f}
\`\`\`${ext}
${fs.readFileSync(f, "utf8")}
\`\`\`
`; } } fs.writeFileSync("plugin-context.md", out); console.log("Done: plugin-context.md"); })'
